INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('c0a2344a-9633-4ac0-93dd-3d58804ee4de', 'e0030000-0000-4000-8000-000000000110', 'en', 'Producer of year-round mobile homes from Białystok, Poland. Steel construction with PUR insulation, on a fixed (FF) or mobile (MP) chassis. More than 2000 homes delivered across Europe. The company holds ISO 9001 and ISO 14001 certificates.', NULL, NULL, '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:31:23.014Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('7fc520e1-aa0a-4535-93f5-a48a13fe5f41', 'e0030000-0000-4000-8000-000000000110', 'de', 'Hersteller ganzjährig nutzbarer mobiler Häuser aus Białystok, Polen. Stahlkonstruktion mit PUR-Dämmung, auf festem (FF) oder mobilem (MP) Fahrgestell. Mehr als 2000 gelieferte Häuser in ganz Europa. Das Unternehmen besitzt die Zertifikate ISO 9001 und ISO 14001.', NULL, NULL, '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:31:23.014Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('5aef500b-97b4-4eab-be56-a04d1951eaf5', 'e0030000-0000-4000-8000-000000000110', 'nl', 'Producent van mobiele huizen voor het hele jaar uit Białystok, Polen. Staalconstructie met PUR-isolatie, op een vast (FF) of mobiel (MP) onderstel. Meer dan 2000 geleverde huizen in heel Europa. Het bedrijf heeft de certificaten ISO 9001 en ISO 14001.', NULL, NULL, '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:31:23.014Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('c05dbc65-c681-4535-a5e0-c74ace15bc86', 'Dom mobilny jest dostarczany w całości z fabryki. Wymagania lokalne (zgłoszenie, podłączenia, posadowienie) zależą od kraju i działki.', 'en', 'The mobile home is delivered complete from the factory. Local requirements (notification, connections, foundation) depend on the country and the plot.', '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:23:06.409Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('a535b585-eea2-44d7-95d9-fcab9a034b49', 'Dom mobilny jest dostarczany w całości z fabryki. Wymagania lokalne (zgłoszenie, podłączenia, posadowienie) zależą od kraju i działki.', 'nl', 'Het mobiele huis wordt compleet vanuit de fabriek geleverd. Lokale eisen (melding, aansluitingen, fundering) hangen af van het land en het perceel.', '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:23:06.409Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('54404f3c-d3c9-4a41-a8fe-9267c194b532', 'Dom mobilny jest dostarczany w całości z fabryki. Wymagania lokalne (zgłoszenie, podłączenia, posadowienie) zależą od kraju i działki.', 'de', 'Das mobile Haus wird komplett ab Werk geliefert. Lokale Anforderungen (Anzeige, Anschlüsse, Aufstellung) hängen vom Land und vom Grundstück ab.', '2026-11-04T19:23:06.409Z'::timestamptz, '2026-11-04T19:23:06.409Z'::timestamptz) ON CONFLICT DO NOTHING;
