INSERT INTO "producer_interior_style" ("id", "producer_id", "name", "description", "sort_order", "created_at", "updated_at", "deleted_at") VALUES ('e9165103-2840-53fb-afc0-00cfebbdcb84', 'e0030000-0000-4000-8000-000000000110', 'Almond Aura', 'Otulająca kompozycja ciepłych beży migdałowych z głębokimi akcentami w tonach kakao i matowej czerni. Nowoczesny, zmysłowy charakter łączy miękką przytulność z wyrazistym akcentem.', 0, '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style" ("id", "producer_id", "name", "description", "sort_order", "created_at", "updated_at", "deleted_at") VALUES ('cf5acf54-0e14-5d0c-a635-206d17696893', 'e0030000-0000-4000-8000-000000000110', 'Calm Stone', 'Stonowana, chłodniejsza, minimalistyczna kompozycja inspirowana estetyką zen i skandynawskim designem. Jasne, nowoczesne i harmonijne wnętrze w neutralnych szaro beżowych tonach.', 1, '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style" ("id", "producer_id", "name", "description", "sort_order", "created_at", "updated_at", "deleted_at") VALUES ('d892b290-2154-5c51-a2f7-a3c7beadde5e', 'e0030000-0000-4000-8000-000000000110', 'Carmel Wood', 'Szlachetne odcienie drewna w tonach karmelu i miodu wnoszą do wnętrza ciepło i naturalność. Efekt wysokiej klasy domowego komfortu, miękki w odbiorze i przytulny, bez rustykalnych skojarzeń.', 2, '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style" ("id", "producer_id", "name", "description", "sort_order", "created_at", "updated_at", "deleted_at") VALUES ('79098d9c-c8f9-509a-ad21-a10e1b57ea66', 'e0030000-0000-4000-8000-000000000110', 'Nude Beige', 'Kompozycja ciepłych beży i subtelnych naturalnych tonów tworzy spokojne, ponadczasowe tło codziennego życia. Czyste, miękkie, uniwersalne wnętrze, eleganckie i przytulne, bez agresywnych kontrastów.', 3, '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style" ("id", "producer_id", "name", "description", "sort_order", "created_at", "updated_at", "deleted_at") VALUES ('937421cb-3311-5bda-a910-828acf106e23', 'e0030000-0000-4000-8000-000000000110', 'New York', 'Kompozycja głębokich, ciemnych tonów z wyrazistymi złotymi akcentami, nawiązująca do wnętrz butikowych hoteli i współczesnego glamouru. Mocny akcent i efekt „wow” z kontrolowaną dawką luksusu.', 4, '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('22ec46ff-adee-4a8f-a273-cc75a5c9e893', 'e9165103-2840-53fb-afc0-00cfebbdcb84', 'en', 'Almond Aura', 'A refined composition of warm almond beiges broken up by deep, expressive accents in cocoa tones and matte black. A modern, sensual character combining soft coziness with a strong accent.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('cf068232-36db-4d8f-a2bc-d5ff58b2ff2a', 'e9165103-2840-53fb-afc0-00cfebbdcb84', 'de', 'Almond Aura', 'Eine raffinierte Komposition aus warmen Mandelbeigetönen, durchbrochen von tiefen, ausdrucksstarken Akzenten in Kakaotönen und mattem Schwarz. Ein moderner, sinnlicher Charakter, der weiche Gemütlichkeit mit einem starken Akzent verbindet.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('f191628a-4a10-401d-bb09-cd792cd02f43', 'e9165103-2840-53fb-afc0-00cfebbdcb84', 'nl', 'Almond Aura', 'Een verfijnde compositie van warme amandelbeige tinten, doorbroken door diepe, expressieve accenten in cacaotinten en mat zwart. Een modern, sensueel karakter dat zachte gezelligheid combineert met een sterk accent.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('0f49199c-6171-44db-b611-9fbea9f08440', 'cf5acf54-0e14-5d0c-a635-206d17696893', 'en', 'Calm Stone', 'A subdued, cooler, minimalist composition inspired by zen aesthetics and Scandinavian design. A light, modern and harmonious interior in neutral gray-beige tones.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('deba1e36-13b2-48d5-a18e-d0d7d60571d9', 'cf5acf54-0e14-5d0c-a635-206d17696893', 'de', 'Calm Stone', 'Eine gedämpfte, kühlere, minimalistische Komposition, inspiriert von Zen-Ästhetik und skandinavischem Design. Ein helles, modernes und harmonisches Interieur in neutralen Grau-Beige-Tönen.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('a0abe3f8-39f7-4f90-8f9a-5b1abf5db9ff', 'cf5acf54-0e14-5d0c-a635-206d17696893', 'nl', 'Calm Stone', 'Een ingetogen, koelere, minimalistische compositie geïnspireerd op zen-esthetiek en Scandinavisch design. Een licht, modern en harmonieus interieur in neutrale grijsbeige tinten.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('da9aff85-fb08-47fd-b7fd-53af34051d71', 'd892b290-2154-5c51-a2f7-a3c7beadde5e', 'en', 'Carmel Wood', 'Noble wood shades in caramel and honey tones bring warmth and naturalness into the space. The impression of refined home premium, soft in perception and cozy, but free from rustic associations.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('0114c7cc-690a-4af5-8f47-655c4a0f0c27', 'd892b290-2154-5c51-a2f7-a3c7beadde5e', 'de', 'Carmel Wood', 'Edle Holztöne in Karamell- und Honigfarben bringen Wärme und Natürlichkeit in den Raum. Der Eindruck von gehobenem Wohnkomfort, weich in der Wahrnehmung und gemütlich, aber frei von rustikalen Assoziationen.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('ada85775-843f-40c4-ad88-ec551ea45f7f', 'd892b290-2154-5c51-a2f7-a3c7beadde5e', 'nl', 'Carmel Wood', 'Edele houttinten in karamel- en honingtinten brengen warmte en natuurlijkheid in de ruimte. De indruk van verfijnde thuiskwaliteit, zacht in beleving en gezellig, maar zonder rustieke associaties.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('ece94149-7ca0-4d3c-881d-8ed17c33985a', '79098d9c-c8f9-509a-ad21-a10e1b57ea66', 'en', 'Nude Beige', 'A composition of warm beiges and subtle natural tones that create a calm, timeless background for everyday life. A clean, soft, universal interior, elegant and cozy, without aggressive contrasts.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('2cc05a60-c295-408d-a5b1-de3fdd87a078', '79098d9c-c8f9-509a-ad21-a10e1b57ea66', 'de', 'Nude Beige', 'Eine Komposition aus warmen Beigetönen und dezenten Naturtönen, die einen ruhigen, zeitlosen Hintergrund für den Alltag schafft. Ein klares, weiches, universelles Interieur, elegant und gemütlich, ohne aggressive Kontraste.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('446c29cf-6ddd-4f7c-bb55-bb4bc00b8553', '79098d9c-c8f9-509a-ad21-a10e1b57ea66', 'nl', 'Nude Beige', 'Een compositie van warme beige en subtiele natuurlijke tinten die een rustige, tijdloze achtergrond voor het dagelijks leven vormt. Een zuiver, zacht, universeel interieur, elegant en gezellig, zonder agressieve contrasten.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('3c123c53-8fda-4a4e-b9c3-47ade81a92a2', '937421cb-3311-5bda-a910-828acf106e23', 'en', 'New York', 'A composition of deep, dark tones with distinctive gold accents, referencing boutique hotel interiors and contemporary glamour. A strong accent and a clear “wow” effect, but with a controlled dose of luxury.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('b005ec91-6e0a-422d-9a7f-6d44798f119f', '937421cb-3311-5bda-a910-828acf106e23', 'de', 'New York', 'Eine Komposition aus tiefen, dunklen Tönen mit markanten Goldakzenten, die an Boutique-Hotel-Interieurs und zeitgenössischen Glamour erinnert. Ein starker Akzent und ein klarer „Wow“-Effekt, aber mit einer kontrollierten Dosis Luxus.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_interior_style_translation" ("id", "style_id", "locale", "name", "description", "created_at", "updated_at") VALUES ('eb05fb95-aa70-461d-a93f-ace7c551a09f', '937421cb-3311-5bda-a910-828acf106e23', 'nl', 'New York', 'Een compositie van diepe, donkere tinten met opvallende gouden accenten, verwijzend naar boetiekhotelinterieurs en eigentijdse glamour. Een sterk accent en een duidelijk “wow”-effect, maar met een beheerste dosis luxe.', '2026-11-04T19:32:02.707Z'::timestamptz, '2026-11-04T19:32:02.707Z'::timestamptz) ON CONFLICT DO NOTHING;
